// ROOT-selected display-only repairs. No field, geometry, clock, actor or save mutation.
const oldRects=[[3526,0,3590,360],[3529,367,3654,451],[3526,460,3590,800],[3526,1130,3590,1320]],band=[3526,800,3590,1130],plateOrigin=[2980,742];
export function createSeamRepairLayer({oldCrops,plate,plateSourceRect}){
 if(!Array.isArray(oldCrops)||oldCrops.length!==4||oldCrops.some((im,i)=>im.width!==oldRects[i][2]-oldRects[i][0]||im.height!==oldRects[i][3]-oldRects[i][1])||JSON.stringify(plateSourceRect)!=='[948,99,1065,679]'||plate.width!==117||plate.height!==580)throw Error('SEAM_CROP_DIMENSIONS');let disposed=false;
 return Object.freeze({draw(ctx,origin){if(disposed)throw Error('SEAM_DISPOSED');if(!Array.isArray(origin)||origin.length!==2||!origin.every(Number.isSafeInteger)||ctx.canvas.width!==960||ctx.canvas.height!==540)throw Error('SEAM_NATIVE_VIEWPORT');const[ox,oy]=origin,visible=([x,y,r,b])=>x<ox+960&&r>ox&&y<oy+540&&b>oy;if(!oldRects.some(visible)&&!visible(band))return false;ctx.save();try{ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.imageSmoothingEnabled=false;for(const[j,[x,y,r,b]]of oldRects.entries())if(visible([x,y,r,b])){const l=Math.max(x,ox),t=Math.max(y,oy),right=Math.min(r,ox+960),bottom=Math.min(b,oy+540);ctx.drawImage(oldCrops[j],l-x,t-y,right-l,bottom-t,l-ox,t-oy,right-l,bottom-t)}if(visible(band)){ctx.imageSmoothingEnabled=true;for(let d=1;d<=8;d++){ctx.save();try{ctx.beginPath();ctx.rect(band[0]+d-ox,band[1]+d-oy,band[2]-band[0]-2*d,band[3]-band[1]-2*d);if(d<8)ctx.rect(band[0]+d+1-ox,band[1]+d+1-oy,band[2]-band[0]-2*d-2,band[3]-band[1]-2*d-2);ctx.clip('evenodd');ctx.globalAlpha=d===8?1:Math.round(d/8*255)/255;ctx.drawImage(plate,-948,-99,1672,941,plateOrigin[0]-ox,plateOrigin[1]-oy,960,540)}finally{ctx.restore()}}}}finally{ctx.restore()}return true},dispose(){disposed=true}})
}
